  $foreignStatus=0;try{Invoke-RestMethod -Uri "$GatewayBaseUrl/api/customer/v1/accounts/2" -Headers $headers|Out-Null}catch{$foreignStatus=$_.Exception.Response.StatusCode.value__}
  $body=@{sourceAccountId='1';destinationAccountId='2';amount='1.00';currency='CNY';reference='idempotency e2e'}|ConvertTo-Json
  $first=Invoke-RestMethod -Method Post -Uri "$GatewayBaseUrl/api/customer/v1/transfers" -Headers ($headers+@{'Idempotency-Key'=$key}) -Body $body
  $transferId=$first.transferId
  $replay=Invoke-RestMethod -Method Post -Uri "$GatewayBaseUrl/api/customer/v1/transfers" -Headers ($headers+@{'Idempotency-Key'=$key}) -Body $body
  $conflictStatus=0;try{Invoke-RestMethod -Method Post -Uri "$GatewayBaseUrl/api/customer/v1/transfers" -Headers ($headers+@{'Idempotency-Key'=$key}) -Body (@{sourceAccountId='1';destinationAccountId='2';amount='2.00';currency='CNY';reference='idempotency e2e'}|ConvertTo-Json)|Out-Null}catch{$conflictStatus=$_.Exception.Response.StatusCode.value__}
  if($foreignStatus -ne 404 -or $fir
st.transferId -ne $replay.transferId -or $conflictStatus -ne 409){throw "Security assertions failed: foreign=$foreignStatus replay=$($replay.transferId) conflict=$conflictStatus"}
  Write-Output "CUSTOMER_ISOLATION=PASS foreignAccount=404 IDEMPOTENCY_REPLAY=PASS IDEMPOTENCY_CONFLICT=PASS"
} finally {
