package local.bank.channel.beneficiaries;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Map;
import java.util.UUID;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.web.bind.annotation.*;

@RestController
public class BeneficiaryController {
  private final JdbcTemplate jdbc;
  public BeneficiaryController(JdbcTemplate jdbc) { this.jdbc = jdbc; }
  @PostMapping("/api/customer/v1/beneficiaries")
  public Map<String, Object> create(@AuthenticationPrincipal Jwt jwt, @RequestBody Request request) throws Exception {
    if (request.accountNumber() == null || request.accountNumber().length() < 6) throw new IllegalArgumentException("accountNumber is invalid");
    String token = sha256(request.accountNumber());
    String id = UUID.randomUUID().toString();
    String last4 = request.accountNumber().substring(request.accountNumber().length() - 4);
    jdbc.update("INSERT INTO beneficiary(beneficiary_id,subject,account_token,account_last4,display_name) VALUES (?,?,?,?,?) ON CONFLICT (subject,account_token) DO NOTHING", UUID.fromString(id), jwt.getSubject(), token, last4, request.displayName());
    return Map.of("beneficiaryId", id, "maskedAccountNumber", "****" + last4, "displayName", request.displayName());
  }
  @GetMapping("/api/customer/v1/beneficiaries")
  public Map<String,Object> list(@AuthenticationPrincipal Jwt jwt){
    var rows=jdbc.query("SELECT beneficiary_id,account_last4,display_name,created_at FROM beneficiary WHERE subject=? ORDER BY created_at DESC",(rs,n)->Map.<String,Object>of("beneficiaryId",rs.getString(1),"maskedAccountNumber","****"+rs.getString(2),"displayName",rs.getString(3),"createdAt",rs.getObject(4).toString()),jwt.getSubject());
    return Map.of("items",rows);
  }
  public record Request(String accountNumber, String displayName) {}
  private static String sha256(String input) throws Exception { byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8)); StringBuilder out = new StringBuilder(
); for (byte b : digest) out.append(String.format("%02x", b)); return out.toString(); }
}

package local.bank.channel.customerprofile;

import java.math.BigDecimal;
import java.util.Map;
import java.util.UUID;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;

@RestController
public class LoanApplicationController {
  private final JdbcTemplate jdbc;
  public LoanApplicationController(JdbcTemplate jdbc){this.jdbc=jdbc;}
  @PostMapping("/api/customer/v1/loans/applications")
  public Map<String,Object> draft(@AuthenticationPrincipal Jwt jwt,@RequestBody Request request){
    if(request.amount()==null||request.amount().signum()<=0||request.termMonths()<1||request.termMonths()>480||request.purpose()==null||request.purpose().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid loan application");
    UUID id=UUID.randomUUID();jdbc.update("INSERT INTO loan_application(application_id,subject,requested_amount,term_months,purpose,status) VALUES(?,?,?,?,?,?)",id,jwt.getSubject(),request.amount(),request.termMonths(),request.purpose(),"DRAFT");return Map.of("applicationId",id.toString(),"status","DRAFT","version",1);
  }
  @PostMapping("/api/customer/v1/loans/applications/{id}/submit")
  public Map<String,Object> submit(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){int n=jdbc.update("UPDATE loan_application SET status='SUBMITTED',version=version+1 WHERE application_id=? AND subject=? AND status='DRAFT'",id,jwt.getSubject());if(n==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Application is not an editable draft");return Map.of("applicationId",id.toString(),"status","SUBMITTED");}
  public record Request(BigDecimal amount,int termMonths,String purpose){}
}

package local.bank.channel.customerprofile;

import java.util.Map;
import java.util.UUID;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;

@RestController
public class LoanScoringController {
  private final JdbcTemplate jdbc;
  public LoanScoringController(JdbcTemplate jdbc){this.jdbc=jdbc;}
  @PostMapping("/api/operations/v1/loans/applications/{id}/score")
  public Map<String,Object> score(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){
    var rows=jdbc.query("SELECT requested_amount,term_months,status FROM loan_application WHERE application_id=?",(rs,n)->Map.<String,Object>of("amount",rs.getBigDecimal(1),"term",rs.getInt(2),"status",rs.getString(3)),id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Application not found");var row=rows.get(0);int score=Math.max(0,Math.min(100,100-((java.math.BigDecimal)row.get("amount")).divide(new java.math.BigDecimal("1000")).intValue()-(Integer)row.get("term")));String reason=score>=60?"Deterministic sandbox score allows review":"Deterministic sandbox score requires manual review";jdbc.update("UPDATE loan_application SET score=?,scoring_reason=?,status='SCORED',version=version+1 WHERE application_id=?",score,reason,id);return Map.of("applicationId",id.toString(),"score",score,"reason",reason,"status","SCORED");
  }
}
